# grpc_tools builds message classes dynamically, so mypy cannot inspect them.
_BrokerEvent: TypeAlias = broker_event_pb2.BrokerEvent  # type: ignore[name-defined,attr-defined]
_UserUttered: TypeAlias = broker_event_pb2.UserUttered  # type: ignore[name-defined,attr-defined]
_BotUttered: TypeAlias = broker_event_pb2.BotUttered  # type: ignore[name-defined,attr-defined]
_MemorySet: TypeAlias = broker_event_pb2.MemorySet  # type: ignore[name-defined,attr-defined]
_ToolExecuted: TypeAlias = broker_event_pb2.ToolExecuted  # type: ignore[name-defined,attr-defined]
_ActionExecuted: TypeAlias = broker_event_pb2.ActionExecuted  # type: ignore[name-defined,attr-defined]


class UnmappedBrokerEventError(RasaException):
    """Raised when a Mantle event or proto payload has no mapper."""


SERIALIZED_EVENT_TYPE_NAMES = frozenset(
    {
        ActionExecuted.type_name,
        BotTurnEnded.type_name,
        BotUttered.type_name,
        ConversationInactive.type_name,
        DialogueStackUpdated.type_name,
        MemoryCleared.type_name,
        MemorySet.type_name,
        OrderedBlockCancelled.type_name,
        OrderedBlockCompleted.type_name,
        OrderedBlockEntered.type_name,
        OrderedBlockInterrupted.type_name,
        OrderedBlockResumed.type_name,
        SessionEnded.type_name,
        SessionStarted.type_name,
        SkillActivated.type_name,
        SkillCancelled.type_name,
        SkillCompleted.type_name,
        SkillInterrupted.type_name,
        SkillResumed.type_name,
        ToolExecuted.type_name,
        TTSFinished.type_name,
        UnsupportedRequestClassified.type_name,
        UserBargeIn.type_name,
        UserInputSuppressed.type_name,
        UserSilenceTimeout.type_name,
        UserUttered.type_name,
    }
)

# Legacy CALM tracker types that this mapper skips. Mantle no longer emits
# flow_* / slot / mcp_tool_executed, but historical trackers still carry them,
# so they stay listed. A new Mantle-only Event type must get a mapper — it must
# not be added here.
UNSERIALIZED_EVENT_TYPE_NAMES = frozenset(
    {
        "action_execution_rejected",
        "active_loop",
        "agent",
        "agent_cancelled",
        "agent_completed",
        "agent_interrupted",
        "agent_processing",
        "agent_resumed",
        "agent_started",
        "cancel_reminder",
        "entities",
        "error",
        "export",
        "flow_cancelled",
        "flow_completed",
        "flow_interrupted",
        "flow_resumed",
        "flow_started",
        "followup",
        "form",
        "form_validation",
        "loop_interrupted",
        "mcp_tool_executed",
        "pause",
        "reminder",
        "reset_slots",
        "restart",
        "resume",
        "rewind",
        "routing_session_ended",
        "slot",
        "undo",
        "user_featurization",
    }
)


def event_to_broker_event(
    event: Event,
    conversation_id: str,
    user_id: Optional[str] = None,
    deployment_environment: Optional[str] = None,
) -> Optional[_BrokerEvent]:
    """Map a supported tracker event to a broker event.

    Args:
        event: Tracker event to map.
        conversation_id: ID of the conversation containing the event.
        user_id: ID of the user participating in the conversation.
        deployment_environment: Name of the Rasa deployment environment.

    Returns:
        The mapped broker event, or ``None`` when the event type is a skipped
        legacy CALM type listed in ``UNSERIALIZED_EVENT_TYPE_NAMES``.

    Raises:
        UnmappedBrokerEventError: If the event type is Mantle-only and has
            no mapper.
    """
    if event.type_name in UNSERIALIZED_EVENT_TYPE_NAMES:
        return None

    payload = _event_to_payload(event)
    if payload is None:
        raise UnmappedBrokerEventError(
            f"No broker mapping for event type '{event.type_name}'. "
            "Add a mapper for this Mantle event, or list a legacy CALM type "
            "in UNSERIALIZED_EVENT_TYPE_NAMES."
        )

    payload_name, payload_message = payload
    broker_event = _BrokerEvent(
        conversation_id=conversation_id,
        timestamp=event.timestamp,
    )
    if event.event_id is not None:
        broker_event.event_id = event.event_id
    if event.sequence is not None:
        broker_event.sequence = event.sequence
    if user_id is not None:
        broker_event.user_id = user_id
    metadata_json, session_id = _envelope_metadata(event)
    if metadata_json is not None:
        broker_event.metadata = metadata_json
    if session_id is not None:
        broker_event.session_id = session_id
    if deployment_environment is not None:
        broker_event.deployment_environment = deployment_environment
    getattr(broker_event, payload_name).CopyFrom(payload_message)
    return broker_event


def broker_event_to_event(
    broker_event: _BrokerEvent,
) -> Optional[Event]:
    """Map a broker event to its tracker event.

    Args:
        broker_event: Broker event to map.

    Returns:
        The mapped tracker event, or ``None`` when the broker event has no
        payload.

    Raises:
        UnmappedBrokerEventError: If the payload has no mapper.
    """
    payload_name = broker_event.WhichOneof("payload")
    if payload_name is None:
        return None

    mapper = _BROKER_EVENT_MAPPERS.get(payload_name)
    if mapper is None:
        raise UnmappedBrokerEventError(
            f"No tracker mapping for broker payload '{payload_name}'. "
            "Add a mapper for this Mantle payload."
        )

    mapped_event = mapper(broker_event)
    if mapped_event is None:
        return None
    _apply_identity(mapped_event, broker_event)
    return mapped_event


def broker_event_to_dict(
    broker_event: _BrokerEvent,
) -> Dict[str, Any]:
    """Serialize a broker event with default ProtoJSON field names and nulls."""
    serialized = json_format.MessageToDict(
        broker_event,
        always_print_fields_with_no_presence=True,
    )
    _null_fill_optional_fields(broker_event, serialized)
    return serialized


def broker_event_from_dict(
    serialized: Dict[str, Any],
) -> _BrokerEvent:
    """Parse a ProtoJSON dictionary into a broker event."""
    return json_format.ParseDict(serialized, _BrokerEvent())


def event_to_broker_event_dict(
    event: Event,
    conversation_id: str,
    user_id: Optional[str] = None,
    rasa_environment: Optional[str] = None,
) -> Optional[Dict[str, Any]]:
    """Map a supported tracker event directly to its ProtoJSON dictionary."""
    broker_event = event_to_broker_event(
        event,
        conversation_id,
        user_id,
        rasa_environment,
    )
    if broker_event is None:
        return None
    return broker_event_to_dict(broker_event)


def broker_event_dict_to_event(serialized: Dict[str, Any]) -> Optional[Event]:
    """Map a ProtoJSON broker event dictionary to its tracker event."""
    return broker_event_to_event(broker_event_from_dict(serialized))


def _event_to_payload(
    event: Event,
) -> Optional[tuple[str, Any]]:
    if isinstance(event, SessionStarted):
        return "session_started", broker_event_pb2.SessionStarted()  # type: ignore[attr-defined]
    if isinstance(event, ConversationInactive):
        return "inactive", broker_event_pb2.ConversationInactive()  # type: ignore[attr-defined]
    if isinstance(event, SessionEnded):
        return "session_ended", broker_event_pb2.SessionEnded()  # type: ignore[attr-defined]
    if isinstance(event, UserUttered):
        return "user", _user_uttered_to_proto(event)
    if isinstance(event, BotUttered):
        return "bot", _bot_uttered_to_proto(event)
    if isinstance(event, UserBargeIn):
        return "user_barge_in", broker_event_pb2.UserBargeIn()  # type: ignore[attr-defined]
    if isinstance(event, TTSFinished):
        return "tts_finished", broker_event_pb2.TTSFinished()  # type: ignore[attr-defined]
    if isinstance(event, UserSilenceTimeout):
        return "user_silence_timeout", broker_event_pb2.UserSilenceTimeout(  # type: ignore[attr-defined]
            timeout=event.timeout
        )
    if isinstance(event, UserInputSuppressed):
        return "user_input_suppressed", broker_event_pb2.UserInputSuppressed(  # type: ignore[attr-defined]
            text=event.text,
            modality=event.modality,
            reason=event.reason,
        )
    if isinstance(event, MemorySet):
        return "memory_set", _memory_set_to_proto(event)
    if isinstance(event, MemoryCleared):
        return "memory_cleared", broker_event_pb2.MemoryCleared(  # type: ignore[attr-defined]
            key=event.key
        )
    if isinstance(event, SkillActivated):
        return "skill_activated", broker_event_pb2.SkillActivated(  # type: ignore[attr-defined]
            skill_id=event.skill_id
        )
    if isinstance(event, SkillCompleted):
        return "skill_completed", broker_event_pb2.SkillCompleted(  # type: ignore[attr-defined]
            skill_id=event.skill_id
        )
    if isinstance(event, SkillCancelled):
        return "skill_cancelled", broker_event_pb2.SkillCancelled(  # type: ignore[attr-defined]
            skill_id=event.skill_id,
            step_id=event.step_id,
        )
    if isinstance(event, SkillInterrupted):
        return "skill_interrupted", broker_event_pb2.SkillInterrupted(  # type: ignore[attr-defined]
            skill_id=event.skill_id,
            step_id=event.step_id,
        )
    if isinstance(event, SkillResumed):
        return "skill_resumed", broker_event_pb2.SkillResumed(  # type: ignore[attr-defined]
            skill_id=event.skill_id,
            step_id=event.step_id,
        )
    if isinstance(event, OrderedBlockEntered):
        return "ordered_block_entered", broker_event_pb2.OrderedBlockEntered(  # type: ignore[attr-defined]
            skill_id=event.skill_id,
            block_id=event.block_id,
        )
    if isinstance(event, OrderedBlockCompleted):
        return "ordered_block_completed", broker_event_pb2.OrderedBlockCompleted(  # type: ignore[attr-defined]
            skill_id=event.skill_id,
            block_id=event.block_id,
            step_id=event.step_id,
        )
    if isinstance(event, OrderedBlockCancelled):
        return "ordered_block_cancelled", broker_event_pb2.OrderedBlockCancelled(  # type: ignore[attr-defined]
            skill_id=event.skill_id,
            block_id=event.block_id,
            step_id=event.step_id,
        )
    if isinstance(event, OrderedBlockInterrupted):
        return (
            "ordered_block_interrupted",
            broker_event_pb2.OrderedBlockInterrupted(  # type: ignore[attr-defined]
                skill_id=event.skill_id,
                block_id=event.block_id,
                step_id=event.step_id,
            ),
        )
    if isinstance(event, OrderedBlockResumed):
        return "ordered_block_resumed", broker_event_pb2.OrderedBlockResumed(  # type: ignore[attr-defined]
            skill_id=event.skill_id,
            block_id=event.block_id,
            step_id=event.step_id,
        )
    if isinstance(event, ToolExecuted):
        return "tool_executed", _tool_executed_to_proto(event)
    if isinstance(event, DialogueStackUpdated):
        return "stack", broker_event_pb2.DialogueStackUpdated(  # type: ignore[attr-defined]
            update=event.update
        )
    if isinstance(event, BotTurnEnded):
        return "bot_turn_ended", broker_event_pb2.BotTurnEnded()  # type: ignore[attr-defined]
    if isinstance(event, ActionExecuted):
        return "action", _action_executed_to_proto(event)
    if isinstance(event, UnsupportedRequestClassified):
        return (
            "unsupported_request_classified",
            broker_event_pb2.UnsupportedRequestClassified(  # type: ignore[attr-defined]
                label=event.label,
                reason=event.reason,
                user_message=event.user_message,
            ),
        )
    return None


def _user_uttered_to_proto(
    event: UserUttered,
) -> _UserUttered:
    payload = _UserUttered()
    if event.text is not None:
        payload.text = event.text
    payload.parse_data.CopyFrom(_dict_to_struct(event.parse_data))
    if event.input_channel is not None:
        payload.input_channel = event.input_channel
    if event.message_id is not None:
        payload.message_id = event.message_id
    if event.anonymized_at is not None:
        payload.anonymized_at = event.anonymized_at.timestamp()
    return payload


def _bot_uttered_to_proto(
    event: BotUttered,
) -> _BotUttered:
    payload = _BotUttered()
    if event.text is not None:
        payload.text = event.text
    payload.data.CopyFrom(_dict_to_struct(event.data))
    if event.anonymized_at is not None:
        payload.anonymized_at = event.anonymized_at.timestamp()
    return payload


def _memory_set_to_proto(event: MemorySet) -> _MemorySet:
    payload = _MemorySet(
        key=event.key,
        value_json=_dump_json(event.value),
    )
    if event.anonymized_at is not None:
        payload.anonymized_at = event.anonymized_at.timestamp()
    return payload


def _tool_executed_to_proto(
    event: ToolExecuted,
) -> _ToolExecuted:
    payload = _ToolExecuted(
        tool_name=event.tool_name,
        arguments_json=_dump_json(event.arguments),
        source=event.source,
        is_error=event.is_error,
    )
    if event.result is not None:
        payload.result_json = _dump_json(event.result)
    if event.error_message is not None:
        payload.error_message = event.error_message
    if event.mcp_server is not None:
        payload.mcp_server = event.mcp_server
    return payload


def _action_executed_to_proto(
    event: ActionExecuted,
) -> _ActionExecuted:
    payload = _ActionExecuted(hide_rule_turn=event.hide_rule_turn)
    if event.action_name is not None:
        payload.name = event.action_name
    if event.policy is not None:
        payload.policy = event.policy
    if event.confidence is not None:
        payload.confidence = event.confidence
    if event.action_text is not None:
        payload.action_text = event.action_text
    return payload


def _user_uttered_from_proto(
    broker_event: _BrokerEvent,
) -> UserUttered:
    payload = broker_event.user
    parse_data = json_format.MessageToDict(payload.parse_data)
    return UserUttered(
        text=_optional_scalar(payload, "text"),
        intent=parse_data.get("intent"),
        entities=parse_data.get("entities"),
        parse_data=parse_data,
        timestamp=broker_event.timestamp,
        input_channel=_optional_scalar(payload, "input_channel"),
        message_id=_optional_scalar(payload, "message_id"),
        metadata=_metadata_from_proto(broker_event),
        anonymized_at=_optional_scalar(payload, "anonymized_at"),
    )


