def _envelope_metadata(event: Event) -> tuple[Optional[str], Optional[str]]:
    """Split envelope metadata JSON from promoted ``session_id``.

    Copies event metadata so tracker events stay unchanged. ``session_id`` is
    a top-level BrokerEvent field, not a key in the metadata document.
    """
    metadata = dict(event.metadata) if event.metadata else {}
    raw_session_id = metadata.get(METADATA_SESSION_ID)
    if isinstance(raw_session_id, str) and raw_session_id.strip():
        session_id = metadata.pop(METADATA_SESSION_ID)
    else:
        session_id = None
    metadata_json = _dump_json(metadata) if metadata else None
    return metadata_json, session_id


def _apply_identity(event: Event, broker_event: _BrokerEvent) -> None:
    if broker_event.HasField("event_id"):
        event.event_id = broker_event.event_id
    if broker_event.HasField("sequence"):
        event.sequence = broker_event.sequence


def _metadata_from_proto(
    broker_event: _BrokerEvent,
) -> Dict[str, Any]:
    metadata = (
        _load_json_object(broker_event.metadata)
        if broker_event.HasField("metadata")
        else {}
    )
    if broker_event.HasField("session_id"):
        metadata[METADATA_SESSION_ID] = broker_event.session_id
    return metadata


def _dict_to_struct(value: Dict[str, Any]) -> struct_pb2.Struct:
    normalized = _load_json_object(_dump_json(value))
    return json_format.ParseDict(normalized, struct_pb2.Struct())


def _dump_json(value: Any) -> str:
    return json.dumps(value)


def _load_json(value: str) -> Any:
    return json.loads(value)


def _load_json_object(value: str) -> Dict[str, Any]:
    decoded = _load_json(value)
    if not isinstance(decoded, dict):
        raise ValueError("Expected a JSON object")
    return decoded


def _optional_scalar(message: Any, field_name: str) -> Any:
    return getattr(message, field_name) if message.HasField(field_name) else None


def _null_fill_optional_fields(
    message: Any,
    serialized: Dict[str, Any],
) -> None:
    for field in message.DESCRIPTOR.fields:
        if _is_unset_optional_field(message, field):
            serialized[field.json_name] = None
            continue
        if (
            field.message_type is not None
            and field.has_presence
            and message.HasField(field.name)
            and isinstance(serialized.get(field.json_name), dict)
        ):
            _null_fill_optional_fields(
                getattr(message, field.name),
                serialized[field.json_name],
            )


def _is_unset_optional_field(message: Any, field: Any) -> bool:
    synthetic_optional = (
        field.containing_oneof is not None
        and field.containing_oneof.name.startswith("_")
    )
    return (
        field.has_presence
        and field.message_type is None
        and (field.containing_oneof is None or synthetic_optional)
        and not message.HasField(field.name)
    )


